def is_quiet_merge(pr):
    # quiet if only docs/infra/markdown changes and no binary bumps
    if pr.files_changed_only_in(['docs/', 'infra/']):
        return True
    return False
// infra/telemetry/telemetry-adapters/lint_adapter.go
func (a *Adapter) Emit(rule string, severity string) {
    a.batch = append(a.batch, fmt.Sprintf("%s:%s", rule, severity))
    if len(a.batch) >= a.batchSize {
        a.flush()
    }
}
